static void help ( char * name ) { puts ( "" ) ; printf ( "usage: %s [-h] [-a][-i iterations] [-p offset][-g] " "[-m mode] [-n][-b vcpu bytes] [-v vcpus][-o] [-r random seed ][-s mem type]" "[-x memslots] [-w percentage][-c physical cpus to run test on]\n" , name ) ; puts ( "" ) ; printf ( " -a: access memory randomly rather than in order.\n" ) ; printf ( " -i: specify iteration counts (default: %" PRIu64 ")\n" , TEST_HOST_LOOP_N ) ; printf ( " -g: Do not enable KVM_CAP_MANUAL_DIRTY_LOG_PROTECT2. This\n" "     makes KVM_GET_DIRTY_LOG clear the dirty log (i.e.\n" "     KVM_DIRTY_LOG_MANUAL_PROTECT_ENABLE is not enabled)\n" "     and writes will be tracked as soon as dirty logging is\n" "     enabled on the memslot (i.e. KVM_DIRTY_LOG_INITIALLY_SET\n" "     is not enabled).\n" ) ; printf ( " -p: specify guest physical test memory offset\n" "     Warning: a low offset can conflict with the loaded test code.\n" ) ; guest_modes_help ( ) ; printf ( " -n: Run the vCPUs in nested mode (L2)\n" ) ; printf ( " -e: Run vCPUs while dirty logging is being disabled.  This\n" "     can significantly increase runtime, especially if there\n" "     isn't a dedicated pCPU for the main thread.\n" ) ; printf ( " -b: specify the size of the memory region which should be\n" "     dirtied by each vCPU. e.g. 10M or 3G.\n" "     (default: 1G)\n" ) ; printf ( " -v: specify the number of vCPUs to run.\n" ) ; printf ( " -o: Overlap guest memory accesses instead of partitioning\n" "     them into a separate region of memory for each vCPU.\n" ) ; printf ( " -r: specify the starting random seed.\n" ) ; backing_src_help ( "-s" ) ; printf ( " -x: Split the memory region into this number of memslots.\n" "     (default: 1)\n" ) ; printf ( " -w: specify the percentage of pages which should be written to\n" "     as an integer from 0-100 inclusive. This is probabilistic,\n" "     so -w X means each page has an X%% chance of writing\n" "     and a (100-X)%% chance of reading.\n" "     (default: 100 i.e. all pages are written to.)\n" ) ; printf ( " -c: Pin tasks to physical CPUs.  Takes a list of comma separated\n" "     values (target pCPU), one for each vCPU, plus an optional\n" "     entry for the main application task (specified via entry\n" "<nr_vcpus + 1>).  If used, entries must be provided for all\n" "     vCPUs, i.e. pinning vCPUs is all or nothing.\n\n" "     E.g. to create 3 vCPUs, pin vCPU0=>pCPU22, vCPU1=>pCPU23,\n" "     vCPU2=>pCPU24, and pin the application task to pCPU50:\n\n" "         ./dirty_log_perf_test -v 3 -c 22,23,24,50\n\n" "     To leave the application task unpinned, drop the final entry:\n\n" "         ./dirty_log_perf_test -v 3 -c 22,23,24\n\n" "     (default: no pinning)\n" ) ; puts ( "" ) ; } 